import {layers,tasks,layerOf,rankArticles,readingQueue,activeMission,relatedTo,escapeHTML as e,safeUrl} from './core.js';

const paths={today:'Today',explore:'Explore',research:'Research',library:'My library',missions:'Research missions',models:'Model studio',settings:'Preferences'};
const glyphs={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',today:'M3 9.5 12 3l9 6.5M5 9v11h5v-6h4v6h5V9',explore:'m16.5 7.5-3 6-6 3 3-6 6-3ZM21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',research:'M8 3H5v18h14V7l-4-4H8Zm7 0v5h4M8 12h8m-8 4h6',library:'M4 4h4v16H4zm6-1h4v17h-4zm6 2 4-1 3 15-4 1z',missions:'M5 21V3m0 1c5-4 9 4 15 0v9c-6 4-10-4-15 0',models:'M9 3h6v4h4v10h-4v4H9v-4H5V7h4V3Zm0 8h6m-6 3h3M2 10h3m14 0h3M2 14h3m14 0h3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-3-5h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',search:'m21 21-5-5M18 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bell:'M18 8a6 6 0 0 0-12 0v5l-2 4h16l-2-4V8ZM10 21h4',arrow:'M4 12h15m-5-5 5 5-5 5',refresh:'M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 3M4 16l2 3a8 8 0 0 0 13-3',plus:'M12 4v16M4 12h16',bookmark:'M6 3h12v18l-6-4-6 4V3Z',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',chevron:'m8 5 7 7-7 7',down:'m5 9 7 7 7-7',check:'m5 12 4 4L20 5',close:'m6 6 12 12M6 18 18 6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-4 9 3 3 5-6',link:'m10 13 4-4m-6 7-2 2a4 4 0 0 1-5-5l4-4m11-1 2-2a4 4 0 0 1 5 5l-4 4',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',list:'M8 6h13M8 12h13M8 18h13M3 6h1m-1 6h1m-1 6h1',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',external:'M14 3h7v7m0-7L10 14M10 4H4v16h16v-6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',logout:'M9 3H4v18h5m6-14 5 5-5 5m-5-5h10'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${glyphs[name]||glyphs.spark}"/></svg>`;
let state=null,page='today',mode='For you',kind='All',layer='All',query='',libraryTab='Saved',missionId='',listMode=false,offline=false,busy=false,readerId=null,poll=null,installPrompt=null;
const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
const dateLabel=iso=>iso?new Date(iso).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Date not supplied';
const saved=id=>state.saved.some(x=>x.id===id);
const navButton=(key,mobile=false)=>`<button data-nav="${key}" class="${page===key?'active':''}">${icon(key)}<span>${mobile&&key==='library'?'Library':mobile&&key==='models'?'Models':paths[key]}</span>${!mobile&&key==='library'?`<span class="count">${state.saved.length}</span>`:''}</button>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('toast');setTimeout(()=>el.classList.remove('toast'),4500);}
async function api(path,body){
 const options=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Samacha':'1'},body:JSON.stringify(body)};
 const r=await fetch(path,options);const data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed');return data;
}
async function sync(){state=await api('/api/state');offline=false;cache();return state;}
function cache(){try{localStorage.setItem('samacha-cache',JSON.stringify({articles:state.articles,saved:state.saved,profile:state.profile,sources:state.sources,missions:state.missions,queries:state.queries,history:[],models:[],routes:{},jobs:[],features:{},schedule:{enabled:false},digest:state.digest,last_refresh:state.last_refresh}));}catch{toast('Browser cache is full. Your data is still saved on the app host.');}}
async function change(path,body,quiet=false){
 if(offline)throw new Error('Reconnect to the app host to make changes. Saved excerpts remain available.');
 const result=await api(path,body);await sync();if(!quiet)render();return result;
}
function showModal(html,reader=false){modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${reader?'reader':''}" role="dialog" aria-modal="true" aria-label="${reader?'Article detail':'App dialog'}" tabindex="-1"><button class="icon-btn modal-close" data-act="close" aria-label="Close dialog">${icon('close')}</button>${html}</section></div>`;document.body.style.overflow='hidden';modalRoot.querySelector('.modal').focus();}
function closeModal(){modalRoot.innerHTML='';document.body.style.overflow='';readerId=null;}
function header(title,description,action=''){return `<div class="heading-row"><div><div class="eyebrow">YOUR PERSONAL KNOWLEDGE SPACE</div><h1>${title}</h1><p class="subhead">${description}</p></div>${action}</div>`;}
function empty(title,description,action=''){return `<div class="empty">${icon('explore')}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function toggle(action,on,extra=''){return `<button class="toggle ${on?'on':''}" data-act="${action}" ${extra} role="switch" aria-checked="${on}" aria-label="${action.replaceAll('-',' ')}"><i></i></button>`;}
function orbitArt(){return `<svg class="orbit-art" viewBox="0 0 310 240" fill="none" aria-hidden="true"><circle cx="182" cy="119" r="73" stroke="currentColor" opacity=".15"/><circle cx="182" cy="119" r="105" stroke="currentColor" opacity=".12" stroke-dasharray="2 5"/><ellipse cx="182" cy="119" rx="125" ry="45" transform="rotate(-37 182 119)" stroke="currentColor" opacity=".45"/><ellipse cx="182" cy="119" rx="102" ry="41" transform="rotate(42 182 119)" stroke="currentColor" opacity=".35"/><circle cx="182" cy="119" r="31" fill="#d4dfb0" fill-opacity=".08" stroke="currentColor" opacity=".6"/><circle cx="182" cy="119" r="9" fill="#d4dfb0"/><circle cx="102" cy="179" r="5" fill="#d4dfb0"/><circle cx="245" cy="154" r="4" fill="#d4dfb0"/><circle cx="224" cy="54" r="3" fill="#d4dfb0"/><text x="164" y="212" class="small-label">FOLLOW YOUR CURIOSITY</text></svg>`;}
function interestMap(){const core=Object.entries(state.profile.topics).filter(([,l])=>l==='Core').map(([t])=>t);return `<div class="interest-map"><svg viewBox="0 0 240 220" role="img" aria-label="Your interests spread from core topics to adjacent topics"><circle class="ring" cx="120" cy="103" r="89"/><circle class="ring" cx="120" cy="103" r="61"/><circle class="core" cx="120" cy="103" r="32"/><text class="center-text" x="120" y="106" text-anchor="middle">${e(core[0]||'Your core')}</text>${[['NLP',74,52],['Hardware',192,83],['AI audio',166,165],['AI video',48,148],['Software',143,24]].map(([t,x,y])=>`<line x1="120" y1="103" x2="${x}" y2="${y}" stroke="currentColor" opacity=".1"/><circle class="node" cx="${x}" cy="${y}" r="5"/><text x="${x}" y="${y+18}" text-anchor="middle">${t}</text>`).join('')}</svg></div>`;}
function rail(){return `<aside class="right-rail"><section class="rail-section"><div class="rail-header"><h3>Your interest orbit</h3><button class="icon-btn" data-nav="explore" aria-label="Edit interest layers">${icon('settings')}</button></div>${interestMap()}<p class="rail-caption">Your core stays yours.<br>A little discovery keeps it growing.</p><div class="legend"><span><i></i>Core</span><span><i></i>Near</span><span><i></i>Adjacent</span></div></section><section class="rail-section"><div class="rail-header"><h3>From your sources</h3><button class="text-btn" data-act="sources">Manage ${icon('arrow')}</button></div>${state.sources.filter(s=>s.enabled).slice(0,4).map(s=>`<div class="rail-source"><div class="source-avatar">${e(s.name[0])}</div><div><strong>${e(s.name)}</strong><small>${s.health==='healthy'?`${s.count} feed entries`:s.health==='unavailable'?'Refresh unavailable':'Ready to connect'}</small></div><i class="status-dot ${s.health}"></i></div>`).join('')}</section><section class="rail-section"><div class="rail-header"><h3>A question worth following</h3></div><div class="rail-mission"><div class="eyebrow">RESEARCH MISSIONS</div><h3>Go a little deeper.</h3><p>A temporary space for a topic on your mind. Your core interests stay intact.</p><button class="text-btn" data-act="new-mission">Start a mission ${icon('arrow')}</button></div></section><div class="rail-bottom">${icon('shield')}<span>Evidence before certainty.<br>Source reputation is never a truth badge.</span></div></aside>`;}
function render(){
 if(!state)return;
 document.body.classList.toggle('dark',state.profile.theme==='dark');
 const detail=['models','settings','missions'].includes(page);
 app.innerHTML=`<aside class="sidebar"><a href="#today" class="logo" data-nav="today"><div class="brandmark">s<span>r</span></div><div class="wordmark">samacha<span>·</span>RAM</div></a><div class="brand-caption">SIGNAL OVER NOISE</div><nav class="nav" aria-label="Main navigation">${['today','explore','research','library'].map(k=>navButton(k)).join('')}<div class="nav-label">YOUR WORKSPACE</div>${['missions','models'].map(k=>navButton(k)).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><strong>${icon('models')} Your models. Your rules.</strong>A specialist for each task. Run locally or bring your own API.<button data-nav="models">Open Model studio ↗</button></div><nav class="nav">${navButton('settings')}</nav><div class="user"><div class="avatar">Y</div><div><strong>Your workspace</strong><small>Personal · self-hosted</small></div><button class="icon-btn" data-act="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="workspace">${offline?'<div class="offline-banner">Offline reading · showing the last cached collection. Reconnect to save changes or run models.</div>':''}<header class="topbar"><div class="crumb">Workspace <span>/</span><strong>${paths[page]}</strong></div><div class="top-actions"><label class="global-search">${icon('search')}<input id="search" type="search" placeholder="Search your world" value="${e(query)}" aria-label="Search articles"><kbd>⌘ K</kbd></label><button class="icon-btn" data-act="digest" aria-label="Open daily briefing">${icon('bell')}</button><button class="icon-btn theme-toggle" data-act="theme" aria-label="Toggle color theme">${icon('sun')}</button></div></header>${detail?`<main class="page-width">${page==='models'?modelsPage():page==='settings'?settingsPage():missionsPage()}</main>`:`<main class="main-layout"><div class="main-content">${page==='today'?todayPage():page==='explore'?explorePage():page==='research'?researchPage():libraryPage()}</div>${rail()}</main>`}<nav class="mobile-nav" aria-label="Mobile navigation">${['today','explore','research','library','models'].map(k=>navButton(k,true)).join('')}<button data-nav="settings" class="${page==='settings'?'active':''}">${icon('settings')}<span>Settings</span></button></nav></div>`;
 bindSearch();
 if(state.jobs.some(j=>['queued','running','downloading'].includes(j.status)))startPoll();
}
function listing(options={}){return rankArticles(state.articles,state.profile,{query,kind,layer,mode,following:state.sources.filter(s=>s.enabled).map(s=>s.id),mission:state.missions.find(m=>m.id===missionId&&activeMission(m)),...options});}
function filters(){return `<div class="filters">${['All','Paper','News','Blog'].map(k=>`<button class="chip ${kind===k?'active':''}" data-kind="${k}">${k==='All'?'All formats':k==='Paper'?'Research papers':k==='News'?'News':'Blogs'}</button>`).join('')}<select class="filter-select" id="layer-filter" aria-label="Filter by interest layer">${['All',...layers.slice(0,4)].map(x=>`<option ${layer===x?'selected':''} value="${x}">${x==='All'?'All layers':x+' interests'}</option>`).join('')}</select></div>`;}
function articleArt(a,i){return `<div class="card-art" data-open="${e(a.id)}" role="button" tabindex="0" aria-label="Open ${e(a.title)}"><span class="art-label">${a.type==='Paper'?'RESEARCH NOTES':'FIELD NOTES'} / ${String(i+1).padStart(2,'0')}</span><svg viewBox="0 0 320 110" fill="none" aria-hidden="true">${i%4===0?`<g stroke="#859a7a" stroke-width=".7" opacity=".6">${Array.from({length:8},(_,j)=>`<path d="M${80+j*15} 95C${130+j*10} 10 ${190-j*8} 135 ${240-j*8} 20"/>`).join('')}<circle cx="155" cy="61" r="31"/><circle cx="200" cy="61" r="31"/><path d="M90 61h160" stroke-dasharray="3 3"/></g>`:i%4===1?`<g stroke="#ab9577" opacity=".7">${Array.from({length:7},(_,j)=>`<rect x="${100+j*15}" y="${27+j*2}" width="47" height="47" rx="2" transform="rotate(25 ${120+j*15} 55)" stroke-width=".7"/>`).join('')}</g>`:i%4===2?`<g stroke="#8c9daa" opacity=".7">${Array.from({length:9},(_,j)=>`<ellipse cx="170" cy="60" rx="${18+j*8}" ry="${5+j*4}" transform="rotate(-20 170 60)" stroke-width=".7"/>`).join('')}</g>`:`<g stroke="#a49296" stroke-width=".7" opacity=".7">${Array.from({length:8},(_,j)=>`<path d="M80 ${25+j*8}Q140 ${95-j*7} 180 ${40+j*3}T260 ${35+j*7}"/>`).join('')}</g>`}</svg></div>`;}
function cards(articles){return `<div class="article-grid">${articles.length?articles.map((a,i)=>`<article class="article-card">${articleArt(a,i)}<div class="card-body"><div class="source-row"><span class="source-dot">${e(a.source[0])}</span><span>${e(a.source.replace(' · reading collection',''))}</span><span class="date">${dateLabel(a.published)}</span></div><button class="card-title" data-open="${e(a.id)}">${e(a.title)}</button><p class="excerpt">${e(a.excerpt||'Metadata only. Open the original source for details.')}</p><div class="card-tags">${a.topics.slice(0,2).map(t=>`<span class="tag">${e(t)}</span>`).join('')}<span class="tag layer">${layerOf(a,state.profile)} interest</span></div><div class="card-footer">${icon('clock')}<span>${a.minutes} min excerpt</span><span class="mini-dot"></span><span>${a.starter?'Starter collection':'Not assessed'}</span><button class="icon-btn ${saved(a.id)?'saved-icon':''}" data-save="${e(a.id)}" aria-label="${saved(a.id)?'Unsave':'Save'} ${e(a.title)}">${icon('bookmark')}</button></div></div></article>`).join(''):empty('A little room for discovery.','No items match these filters. Try another topic or refresh your sources.',`<button class="outline-btn" data-act="reset-filters">Reset filters</button>`)}</div>`;}
function todayPage(){const rows=listing();const live=state.articles.filter(a=>!a.starter).length;return `${header('Follow your curiosity.','A thoughtful selection from the worlds you care about.',`<button class="outline-btn" data-act="refresh">${icon('refresh',busy?'loading-spinner':'')} ${busy?'Refreshing':'Refresh sources'}</button>`)}<section class="briefing"><div class="briefing-copy"><div class="eyebrow">YOUR DAILY DOSE OF PERSPECTIVE</div><h2>A little signal.<br>A lot of possibility.</h2><p>The ideas worth your attention, brought together.<br>Make space for ${state.profile.budget} minutes of curiosity.</p><button class="primary-btn" data-act="digest">Open your briefing ${icon('arrow')}</button><span class="brief-meta">${readingQueue(rows,state.profile.budget).length} reads · your pace</span></div>${orbitArt()}</section><section><div class="feed-heading"><h2>On your radar <span class="badge-num">${rows.length}</span></h2><button class="icon-btn" data-act="list" aria-label="Toggle list layout">${icon(listMode?'grid':'list')}</button></div><div class="segmented">${['For you','Following'].map(m=>`<button data-mode="${m}" class="${mode===m?'active':''}">${m}</button>`).join('')}<button data-nav="missions">Your missions ${icon('chevron')}</button></div>${filters()}${missionId?`<div class="info">${icon('missions')}<span>Mission: ${e(state.missions.find(m=>m.id===missionId)?.title||'')} · temporary focus; global interests unchanged</span><button class="text-btn" data-act="reset-filters">Leave mission</button></div>`:''}<p class="source-note">${icon('info')}${live?`${live} feed records · source excerpts, not verified full articles`:'Start with a historical reading collection. Refresh to gather live feed entries.'}</p><div class="${listMode?'list-mode':''}">${cards(rows)}</div><p class="footer-note">You decide what matters. We help you connect the dots.</p></section>`;}
function explorePage(){return `${header('Your world, in layers.','Shape the subjects you follow. Explicit choices always come first.',`<button class="outline-btn" data-act="sources">${icon('plus')} Sources</button>`)}<section class="panel"><div class="panel-title"><h2>Your interest orbit</h2><span class="tag">Editable · always</span></div><p class="description">Core is your focus. Near and adjacent broaden the view. Discovery leaves room for the unexpected.</p>${Object.entries(state.profile.topics).map(([topic,l])=>`<div class="topic-row"><div><strong>${e(topic)}</strong><small>${({LLMs:'Models, reasoning, retrieval, and inference',NLP:'Language, translation, and text understanding',Hardware:'Chips, accelerators, and efficient systems','AI audio':'Speech, sound, and voice technology','AI video':'Visual understanding and video generation',Software:'Tools, architecture, and engineering'})[topic]||'Your custom subject'}</small></div><select class="control" style="width:125px" data-topic="${e(topic)}" aria-label="Interest layer for ${e(topic)}">${layers.map(x=>`<option ${x===l?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')}</section><section class="panel"><div class="panel-title"><h2>Explore the collection</h2><button class="text-btn" data-act="save-query">Save this search ${icon('bookmark')}</button></div>${filters()}${cards(listing({mode:'For you'}))}</section>`;}
function researchPage(){return `${header('Ideas worth a closer read.','Papers, author-reported findings, and the context around them.')}<div class="info">${icon('research')}<span>Research status and factual support are separate. An arXiv record does not by itself establish peer review or independent reproduction.</span></div><div class="filters"><button class="chip active">All research papers</button><button class="text-btn" data-act="save-query">${icon('bookmark')} Save search</button><select class="filter-select" id="layer-filter" aria-label="Research interest layer">${['All',...layers.slice(0,4)].map(l=>`<option ${l===layer?'selected':''}>${l}</option>`).join('')}</select></div>${cards(listing({kind:'Paper',mode:'For you'}))}`;}
function libraryPage(){const rows=listing({mode:'For you',kind:'All',layer:'All'}).filter(a=>saved(a.id));return `${header('Keep the good things.','A place for the ideas you want to come back to.',`<a class="outline-btn" href="/api/export" download>${icon('download')} Export library</a>`)}<div class="library-tabs">${['Saved','History','Saved searches'].map(t=>`<button class="${libraryTab===t?'active':''}" data-library="${t}">${t}${t==='Saved'?` (${state.saved.length})`:''}</button>`).join('')}</div>${libraryTab==='Saved'?cards(rows):libraryTab==='History'?`<section class="panel"><div class="panel-title"><h2>Your reading trail</h2><button class="text-btn danger" data-act="clear-history">Clear history</button></div><p class="description">Metadata opens, summary views, external-link opens, and manually marked reads are recorded separately.</p>${state.history.length?state.history.map(h=>{const a=state.articles.find(a=>a.id===h.article);return a?`<div class="history-row"><button data-open="${e(a.id)}" style="text-align:left"><strong>${e(a.title)}</strong><small>${dateLabel(h.created)}</small></button><span class="history-kind">${e(h.kind.replaceAll('_',' '))}</span></div>`:'';}).join(''):empty('Your trail starts here.','Reading events appear here when tracking is enabled.')}</section>`:`<section class="panel">${state.queries.length?state.queries.map(q=>`<div class="history-row"><button data-query="${e(q.query)}">${icon('search')} ${e(q.query)}</button><button class="icon-btn danger" data-query-delete="${e(q.id)}" aria-label="Delete search">${icon('trash')}</button></div>`).join(''):empty('Keep a question open.','Search a subject, then save the query from Explore or Research.')}</section>`}`;}
function missionsPage(){return `${header('A question to follow.','Temporary focus. Lasting discoveries. Your global interests stay intact.',`<button class="primary-btn" data-act="new-mission">${icon('plus')} New mission</button>`)}${state.missions.length?`<div class="model-grid">${state.missions.map(m=>`<section class="panel"><span class="model-local">${activeMission(m)?'ACTIVE MISSION':'ARCHIVED'}</span><h2>${e(m.title)}</h2><p class="description">Until ${dateLabel(m.expires)} · ${e(m.topics.join(', '))}</p><div class="reader-actions"><button class="outline-btn" data-mission="${e(m.id)}">Explore mission ${icon('arrow')}</button><button class="icon-btn danger" data-mission-delete="${e(m.id)}" aria-label="Delete mission">${icon('trash')}</button></div></section>`).join('')}</div>`:empty('Follow your next question.','Create a focused collection for a topic you are exploring this week.',`<button class="primary-btn" data-act="new-mission">Start a mission ${icon('plus')}</button>`)}`;}
const taskHints={classification:'Suggest topics with a specialist classifier',summarization:'Extractive or model-generated overviews',embeddings:'Represent source text as vectors',reranking:'Evaluate relevance to a question',evidence:'Draft an assessment for human review',qa:'Find answers within the available source'};
function providerOptions(task,selected,none=false){return `${none?'<option value="none">No fallback</option>':''}<option value="builtin" ${selected==='builtin'?'selected':''}>${['classification','summarization','qa'].includes(task)?'Built-in baseline':'Unconfigured baseline'}</option>${state.models.filter(m=>m.capabilities.includes(task)).map(m=>`<option value="${e(m.id)}" ${selected===m.id?'selected':''}>${e(m.name)}${m.local?' · local':' · API'}</option>`).join('')}`;}
function modelsPage(){return `${header('The right model for the job.','Your providers, your local models, your choice. No single-model dependency.',`<button class="primary-btn" data-act="add-model">${icon('plus')} Add model</button>`)}<div class="info">${icon('shield')}<span>API keys are encrypted on your app host and never returned to this page. Local inference runs on the app host, not directly on this phone. Cloud fallbacks are off by default.</span></div><section class="panel"><div class="panel-title"><h2>Your task pipeline</h2><span class="tag">6 independent routes</span></div><p class="description">Choose a specialist for each task. A fallback runs only if the primary route fails and your privacy policy allows it.</p><div class="route-labels"><span>Task</span><span>Primary model</span><span>Fallback model</span></div>${Object.entries(tasks).map(([task,label])=>{const r=state.routes[task]||{primary:'builtin',fallback:'none'};return `<div class="route-row"><label><strong>${label}</strong><small>${taskHints[task]}</small></label><select class="control" data-route="${task}" data-slot="primary" aria-label="Primary ${label} model">${providerOptions(task,r.primary)}</select><select class="control" data-route="${task}" data-slot="fallback" aria-label="Fallback ${label} model">${providerOptions(task,r.fallback,true)}</select></div>`;}).join('')}<div class="setting-row"><div><strong>Local-only processing</strong><small>Block every cloud model, even if selected above.</small></div>${toggle('local-only',state.profile.local_only)}</div><div class="setting-row"><div><strong>Allow cloud fallback</strong><small>Only for providers you explicitly allowed to receive source text.</small></div>${toggle('cloud-fallback',state.profile.cloud_fallback)}</div></section><div class="panel-title"><h2>Your model library</h2><button class="text-btn" data-act="download-model">Download or import ${icon('download')}</button></div><div class="model-grid">${state.models.length?state.models.map(m=>`<article class="provider-card"><span class="model-local">${m.local?'LOCAL · APP HOST':'API · USER CONFIGURED'}</span><h3>${e(m.name)}</h3><p class="model-name">${e(m.model)}</p><p class="source-note">${e(m.kind)} ${m.has_key?'· key encrypted':''}</p><div class="card-tags">${m.capabilities.map(t=>`<span class="tag">${tasks[t]}</span>`).join('')}</div><div class="actions"><button class="outline-btn tiny" data-model-test="${e(m.id)}">${icon('spark')} Test inference</button><button class="outline-btn tiny" data-model-edit="${e(m.id)}">Edit</button><button class="icon-btn danger" data-model-delete="${e(m.id)}" aria-label="Delete model">${icon('trash')}</button></div></article>`).join(''):empty('Bring your own intelligence.','Use API providers, Ollama, a llama.cpp server, or a compatible safetensors model bundle.',`<button class="outline-btn" data-act="add-model">Add your first model</button>`)}</div><section class="panel" style="margin-top:24px"><div class="panel-title"><h2>Try your pipeline</h2><span class="tag">Runs the selected route</span></div><form id="playground"><div class="field-row"><div class="field"><label for="play-task">Task</label><select id="play-task" name="task">${Object.entries(tasks).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="field"><label for="play-question">Question or claim (for Q&A / review)</label><input id="play-question" name="question" placeholder="What does this source actually support?"></div></div><div class="field"><label for="play-text">Source text</label><textarea id="play-text" name="text" maxlength="24000" required placeholder="Paste an excerpt to classify, summarize, embed, or examine…"></textarea><small>Only this text and your question are sent to the selected model. Model output is not a verification verdict.</small></div><button class="primary-btn" type="submit">${icon('spark')} Run task</button><div id="play-result"></div></form></section>${state.jobs.length?`<section class="panel"><h2>Processing activity</h2>${state.jobs.slice().reverse().slice(0,8).map(j=>`<div class="job-row"><span>${e(j.repo||'Source refresh')}${j.error?`<small class="danger"> · ${e(j.error)}</small>`:''}</span><span>${e(j.status)}</span></div>`).join('')}</section>`:''}`;}
function settingsPage(){return `${header('Make it feel like yours.','Control your reading pace, privacy, and daily routine.')}<section class="panel"><h2>Your reading rhythm</h2><div class="setting-row"><div><strong>Daily reading budget</strong><small>Estimated excerpt-reading time, not full-paper duration.</small></div><div class="budget-buttons">${[5,15,30].map(n=>`<button class="${state.profile.budget===n?'active':''}" data-budget="${n}">${n} min</button>`).join('')}</div></div><form id="schedule-form"><div class="field-row" style="margin-top:20px"><div class="field"><label for="digest-hour">Daily briefing time</label><input id="digest-hour" name="digest_hour" type="time" value="${state.profile.digest_hour}" required></div><div class="field"><label for="timezone">Timezone</label><input id="timezone" name="timezone" value="${e(state.profile.timezone)}" required></div></div><button class="outline-btn" type="submit">Save routine</button></form><div class="setting-row"><div><strong>Daily refresh & briefing</strong><small>Runs once daily while the app host is running. In-app briefing only; push alerts are not configured.</small></div>${toggle('schedule',state.schedule.enabled)}</div><div class="setting-row"><div><strong>Dark appearance</strong><small>A quieter space for late reading.</small></div>${toggle('theme',state.profile.theme==='dark')}</div><div class="setting-row"><div><strong>Install on this device</strong><small>On supported browsers, add samacha-RAM to your home screen. HTTPS or localhost is required for offline installation.</small></div><button class="outline-btn" data-act="install">${icon('download')} Install</button></div></section><section class="panel"><h2>Your privacy</h2><div class="setting-row"><div><strong>Reading history</strong><small>Record in-app actions. Turning this off creates no new reading events or saved model outputs.</small></div>${toggle('tracking',state.profile.tracking)}</div><div class="setting-row"><div><strong>Clear reading history</strong><small>Deletes recorded reading actions. Saved articles and notes remain.</small></div><button class="outline-btn danger" data-act="clear-history">Clear history</button></div><div class="setting-row"><div><strong>Export your library</strong><small>Includes preferences, saved records, notes, and history. API keys are excluded.</small></div><a class="outline-btn" href="/api/export" download>${icon('download')} Export JSON</a></div></section><section class="panel"><h2>About this release</h2><p class="description">A self-hosted, single-owner reading workspace. Your browser caches source excerpts and saved notes for offline access. The app host stores your records in SQLite. This is an installable web app, not a native Android APK.</p><p class="description">Live feeds depend on publisher availability. Model drafts are labeled; no source or model automatically receives a verified badge. Full-paper reading and downloads open the publisher's page. Automatic fact verification, full-text scraping, multi-user sync, and native on-phone inference are not enabled.</p><button class="text-btn" data-act="onboarding">Revisit welcome setup ${icon('arrow')}</button></section>`;}
function bindSearch(){const search=document.querySelector('#search');let t;search?.addEventListener('input',()=>{const pos=search.selectionStart;query=search.value;clearTimeout(t);t=setTimeout(()=>{if(['models','settings','missions'].includes(page))page='today';render();const f=document.querySelector('#search');f.focus();f.setSelectionRange(pos,pos);},220);});}
async function openArticle(id){const a=state.articles.find(a=>a.id===id);if(!a)return;readerId=id;
 if(!offline&&state.profile.tracking){try{await change('/api/history',{id,kind:'metadata_open'},true);}catch{}}
 const related=relatedTo(a,state.articles);
 const note=state.saved.find(x=>x.id===id)?.note||'';
 showModal(`<div class="reader-header"><div class="eyebrow">${e(a.type)} · ${a.starter?'HISTORICAL STARTER RECORD':'PUBLISHER FEED'}</div><h2>${e(a.title)}</h2><p class="reader-meta">${e(a.authors)} · ${dateLabel(a.published)}</p><div class="card-tags">${a.topics.map(t=>`<span class="tag">${e(t)}</span>`).join('')}<span class="tag layer">${layerOf(a,state.profile)} interest</span></div></div><div class="info">${icon('info')}<span><strong>${e(a.access)}.</strong> ${e(a.publication)}. Evidence: not assessed. ${a.starter?'This is a historical editorial reading record, not live news.':''}</span></div><div class="reader-text">${e(a.excerpt||'No excerpt is available. Visit the original publisher for the article.')}</div><div class="reader-actions"><a class="primary-btn" href="${e(safeUrl(a.url))}" data-original="${e(id)}" target="_blank" rel="noopener noreferrer">Read original ${icon('external')}</a><button class="outline-btn" data-summary="${e(id)}">${icon('spark')} Summarize excerpt</button><button class="outline-btn" data-save="${e(id)}">${icon('bookmark')} ${saved(id)?'Saved':'Save'}</button><button class="outline-btn" data-mark-read="${e(id)}">${icon('check')} Mark read</button></div><p class="source-note">${icon('shield')}Original-link opens do not count as reading the full paper.</p><div id="reader-result"></div><section class="reader-section"><h3>Why this is in your orbit</h3><p class="subhead">Matches ${e(a.topics.map(t=>t+' ('+(state.profile.topics[t]||'Discovery')+')').join(', '))}. Your explicit layer choices drive this ranking. No behavioral promotion is applied.</p></section><section class="reader-section"><h3>Keep a thought</h3><form id="note-form" data-id="${e(id)}"><div class="field"><textarea name="note" maxlength="20000" placeholder="A question, a connection, a thought to come back to…">${e(note)}</textarea></div><button class="outline-btn" type="submit">Save note to library</button></form></section><section class="reader-section"><h3>Connected by topic</h3><p class="source-note">Shared subjects only — these are not established citations, follow-ups, or causal links.</p>${related.map(({article:r,topics})=>`<button class="related-item" data-open="${e(r.id)}"><strong>${e(r.title)}</strong><small>Shared topic: ${e(topics.join(', '))}${state.history.some(h=>h.article===r.id)?' · previously opened in this app':''}</small></button>`).join('')||'<p class="source-note">No related records in your current collection.</p>'}</section><section class="reader-section"><h3>Ask this excerpt</h3><form id="reader-qa" data-id="${e(id)}"><div class="field"><input name="question" required maxlength="2000" placeholder="What can I learn from this source?"></div><button class="outline-btn" type="submit">Ask your Q&A route ${icon('arrow')}</button></form><div id="qa-result"></div></section>`,true);
 readerId=id;
}
function resultHTML(r){const v=r.result;return `<div class="result">${v.sentences?(!v.sentences.length?'<p>Not enough matching evidence in this source.</p>':v.sentences.map(s=>`<p>${e(s.text)}</p><blockquote>${e(s.quote)}</blockquote>`).join('')):v.generated_text?`<p>${e(v.generated_text)}</p>`:v.vectors?`<p>${v.vectors.length} vector(s) · ${v.dimensions} dimensions</p><p>${e(JSON.stringify(v.vectors[0].slice(0,8)))} …</p>`:`<p>${e(JSON.stringify(v,null,2))}</p>`}${v.notice?`<p class="source-note">${e(v.notice)}</p>`:''}<div class="result-meta">${e(r.provider)} · ${e(r.model)} · ${r.local?'local to app host':'API call'} · ${r.milliseconds} ms${r.fallback_used?' · fallback used':''}${r.access?' · '+e(r.access):''}</div></div>`;}
function onboarding(){showModal(`<div class="eyebrow">WELCOME TO YOUR ORBIT</div><h2>What sparks your curiosity?</h2><p class="modal-sub">Start with a core interest. You can shape every layer as you go.</p><div class="onboarding-grid">${Object.keys(state.profile.topics).map(t=>`<button class="onboarding-choice ${state.profile.topics[t]==='Core'?'selected':''}" data-core="${e(t)}"><strong>${e(t)}</strong><small>${e(state.profile.topics[t])} interest</small></button>`).join('')}</div><div class="info" style="margin-top:20px">${icon('shield')}<span>Your explicit interests drive your feed. Change them at any time. Source excerpts and model drafts are never presented as independently verified news.</span></div><div class="modal-actions"><button class="primary-btn" data-act="finish-onboarding">Find my signal ${icon('arrow')}</button></div>`);}
function missionModal(){const expires=new Date(Date.now()+7*86400000).toISOString().slice(0,10);showModal(`<h2>A new line of inquiry.</h2><p class="modal-sub">A temporary focus that leaves your global interests untouched.</p><form id="mission-form"><div class="field"><label for="mission-title">What are you exploring?</label><input id="mission-title" name="title" placeholder="Low-latency local speech models" required maxlength="120"></div><div class="field"><label for="mission-expires">Follow until</label><input type="date" id="mission-expires" name="expires" value="${expires}" required></div><div class="field"><label>Related topics</label>${Object.keys(state.profile.topics).map(t=>`<label class="check"><input name="topics" value="${e(t)}" type="checkbox">${e(t)}</label>`).join('')}</div><button class="primary-btn" type="submit">Create mission ${icon('arrow')}</button></form>`);}
function sourceModal(){showModal(`<h2>A well-chosen reading list.</h2><p class="modal-sub">Follow public RSS, Atom, or JSON Feed sources. Full-text rights remain with the publisher.</p><table class="source-table">${state.sources.map(s=>`<tr><td><strong>${e(s.name)}</strong><div class="source-url">${e(s.url)}</div><span class="health">${e(s.health.replaceAll('_',' '))}${s.last_success?' · last success '+dateLabel(s.last_success):''}</span></td><td>${toggle('source-toggle',s.enabled,`data-id="${e(s.id)}"`)}</td></tr>`).join('')}</table><div class="reader-section"><form id="source-form"><div class="field-row"><div class="field"><label for="source-name">Source name</label><input id="source-name" name="name" required placeholder="A favorite publication"></div><div class="field"><label for="source-url">Public feed URL</label><input id="source-url" name="url" type="url" required placeholder="https://example.org/feed.xml"></div></div><div class="field"><label for="source-kind">Content type</label><select name="kind" id="source-kind"><option>News</option><option>Blog</option><option>Paper</option></select></div><button class="outline-btn" type="submit">${icon('plus')} Add feed</button></form></div><div class="reader-actions" style="margin-top:20px"><button class="outline-btn" data-act="export-opml">${icon('download')} Export OPML</button><label class="outline-btn" style="cursor:pointer">Import OPML<input type="file" id="opml-file" accept=".opml,.xml" hidden></label></div>`);}
function providerModal(id){const m=state.models.find(m=>m.id===id)||{};showModal(`<h2>${id?'Edit your model.':'Add a specialist.'}</h2><p class="modal-sub">Register a model, then assign it to individual tasks in your pipeline.</p><form id="model-form" data-id="${e(id||'')}"><div class="field-row"><div class="field"><label for="model-name">Display name</label><input id="model-name" name="name" value="${e(m.name||'')}" placeholder="My summarizer" required maxlength="100"></div><div class="field"><label for="model-kind">Adapter</label><select id="model-kind" name="kind">${[['openai','OpenAI-compatible API / llama.cpp'],['ollama','Ollama · app-host loopback'],['transformers','Downloaded Transformers bundle']].map(([k,l])=>`<option value="${k}" ${m.kind===k?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="field"><label for="model-id">Model ID / local bundle folder</label><input id="model-id" name="model" value="${e(m.model||'')}" placeholder="Provider model ID or bundle folder name" required maxlength="300"><small>Downloaded models: use a folder under data/models/. GGUF: serve it with llama.cpp and use its compatible API.</small></div><div id="endpoint-fields"><div class="field"><label for="model-endpoint">API base URL</label><input id="model-endpoint" name="endpoint" value="${e(m.endpoint||'')}" placeholder="https://provider.example/v1"><small>Compatible API: include /v1. Ollama: http://localhost:11434. No query strings or embedded credentials.</small></div><div class="field"><label for="model-key">API key</label><input id="model-key" name="key" type="password" autocomplete="new-password" placeholder="${m.has_key?'Key saved · leave blank to keep it':'Optional for local runtimes'}"><small>Encrypted at rest on the app host. Never included in exports or logs.</small></div><label class="check"><input name="clear_key" type="checkbox">Remove the previously saved key</label><label class="check"><input name="local" type="checkbox" ${m.local?'checked':''}>Local endpoint on the app host (loopback only)</label><label class="check"><input name="allow_cloud" type="checkbox" ${m.allow_cloud?'checked':''}>Allow the selected source text and question to be sent to this cloud endpoint</label></div><div class="field"><label>Tasks this model supports</label><small>Match the model architecture to its task. A chat model is not automatically an embedding or classification specialist.</small><div class="field-row" style="margin-top:12px">${Object.entries(tasks).map(([k,v])=>`<label class="check"><input name="capabilities" value="${k}" type="checkbox" ${m.capabilities?.includes(k)?'checked':''}>${v}</label>`).join('')}</div><small>Transformers bundles: register one task per model record. Local classification expects zero-shot NLI; summarization expects a summarization-compatible seq2seq model.</small></div><button class="primary-btn" type="submit">Save model ${icon('arrow')}</button></form>`);toggleAdapter();}
function toggleAdapter(){const f=document.querySelector('#model-form');if(!f)return;const local=f.elements.kind.value==='transformers';document.querySelector('#endpoint-fields').hidden=local;f.elements.endpoint.required=!local;}
async function downloadModal(){const bundles=offline?[]:(await api('/api/bundles')).bundles;showModal(`<h2>A model of your own.</h2><p class="modal-sub">Download or import a compatible Transformers bundle. It runs on the app host. No model is downloaded automatically.</p><div class="info">${icon('info')}<span>${state.features.transformers_installed?'Optional model runtime detected.':'Install requirements-models.txt on the app host to enable local inference and Hub downloads.'} Use safetensors weights and tokenizer/config files. Pickle weights and executable model code are not accepted.</span></div><form id="download-form"><div class="field"><label for="download-repo">Hugging Face model repository</label><input id="download-repo" name="repo" placeholder="owner/model-name" required></div><div class="field"><label for="download-revision">Exact model commit revision</label><input id="download-revision" name="revision" pattern="[a-fA-F0-9]{40}" placeholder="40-character commit SHA" required><small>Pin a revision from the model's Files and versions page. Maximum managed download: 4 GiB.</small></div><label class="check"><input type="checkbox" name="license_ack" required>I reviewed the model license, task compatibility, and storage requirements, and want to download its files.</label><button class="primary-btn" type="submit">Download to app host ${icon('download')}</button></form><section class="reader-section"><h3>Already downloaded?</h3><p class="modal-sub">Choose a complete model folder to import config, tokenizer, and safetensors files. Files are uploaded to your own app host.</p><label class="outline-btn" style="cursor:pointer">${icon('plus')} Choose model folder<input id="bundle-files" type="file" webkitdirectory directory multiple hidden></label><p id="import-progress" class="source-note"></p>${bundles.length?`<div class="result">${bundles.map(b=>`${e(b.name)} · ${(b.bytes/1024**2).toFixed(0)} MiB`).join('<br>')}</div>`:''}<p class="source-note" style="margin-top:12px">After download/import, Add model → Downloaded Transformers bundle → enter its folder name and choose one task. For GGUF use a llama.cpp endpoint.</p></section>`);}
async function digestModal(){let digest;if(!offline){digest=await change('/api/digest',{},true);}else digest=state.digest||{article_ids:readingQueue(listing(),state.profile.budget).map(a=>a.id)};const rows=digest.article_ids.map(id=>state.articles.find(a=>a.id===id)).filter(Boolean);showModal(`<div class="eyebrow">A FINITE MOMENT OF DISCOVERY</div><h2>Your ${state.profile.budget}-minute briefing.</h2><p class="modal-sub">Read a little. Leave with something new. Times refer to excerpts, not full articles.</p>${!rows.length?empty('No matches today.','Refresh sources or adjust your interests.'):rows.map((a,i)=>`<button class="related-item" data-open="${e(a.id)}"><span class="inline-label">${String(i+1).padStart(2,'0')} · ${e(a.topics[0])} · ${a.minutes} MIN</span><strong style="font:21px/1.4 var(--serif);margin:7px 0">${e(a.title)}</strong><small>${e(a.source)} · ${a.starter?'Historical starter record':'Feed excerpt · not assessed'}</small></button>`).join('')}<p class="footer-note">That is enough for now. Your next question can wait.</p>`);}
function downloadFile(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function startPoll(){if(poll)return;poll=setInterval(async()=>{try{await sync();if(!state.jobs.some(j=>['queued','running','downloading'].includes(j.status))){clearInterval(poll);poll=null;busy=false;render();toast('Processing finished. Check source health or Model studio for results.');}else if(page==='models'&&!modalRoot.children.length)render();}catch{}},3000);}
async function action(target){
 if(target.dataset.nav){page=target.dataset.nav;missionId='';closeModal();render();window.scrollTo(0,0);return;}
 if(target.dataset.open){await openArticle(target.dataset.open);return;}
 if(target.dataset.save){const id=target.dataset.save;await change('/api/save',{id,active:!saved(id)},true);toast(saved(id)?'Saved to your library.':'Removed from saved items.');const current=readerId;render();if(current)await openArticle(current);return;}
 if(target.dataset.kind){kind=target.dataset.kind;render();return;}
 if(target.dataset.mode){mode=target.dataset.mode;render();return;}
 if(target.dataset.library){libraryTab=target.dataset.library;render();return;}
 if(target.dataset.query){query=target.dataset.query;page='today';kind='All';layer='All';render();return;}
 if(target.dataset.queryDelete){await change('/api/query/delete',{id:target.dataset.queryDelete});return;}
 if(target.dataset.mission){const m=state.missions.find(m=>m.id===target.dataset.mission);if(!activeMission(m)){toast('This mission is archived. Create a new one to follow it again.');return;}missionId=m.id;page='today';mode='For you';kind='All';query='';render();toast('Mission view: '+m.title);return;}
 if(target.dataset.missionDelete){if(confirm('Delete this mission? Your saved articles remain.'))await change('/api/mission/delete',{id:target.dataset.missionDelete});return;}
 if(target.dataset.modelEdit){providerModal(target.dataset.modelEdit);return;}
 if(target.dataset.modelDelete){if(confirm('Remove this model configuration? Assigned routes return to the baseline. Files on disk are kept.'))await change('/api/models/delete',{id:target.dataset.modelDelete});return;}
 if(target.dataset.modelTest){target.disabled=true;try{const r=await api('/api/models/test',{id:target.dataset.modelTest});showModal(`<h2>Inference test completed.</h2><p class="modal-sub">An actual task request was made. This tests one task, not the quality of all capabilities.</p>${resultHTML(r)}`);}finally{target.disabled=false;}return;}
 if(target.dataset.summary){target.disabled=true;try{const id=target.dataset.summary;const r=await api('/api/run',{article_id:id,task:'summarization'});if(state.profile.tracking)await change('/api/history',{id,kind:'summary_open'},true);document.querySelector('#reader-result').innerHTML=resultHTML(r);}finally{target.disabled=false;}return;}
 if(target.dataset.markRead){await change('/api/history',{id:target.dataset.markRead,kind:'mark_read'},true);toast(state.profile.tracking?'Manually marked as read.':'History is paused. No reading event was saved.');return;}
 if(target.dataset.core){const t=target.dataset.core;await change('/api/profile',{topics:{...state.profile.topics,[t]:state.profile.topics[t]==='Core'?'Near':'Core'}},true);onboarding();return;}
 switch(target.dataset.act){
 case 'close':closeModal();break;
 case 'sources':sourceModal();break;
 case 'new-mission':missionModal();break;
 case 'add-model':providerModal();break;
 case 'download-model':await downloadModal();break;
 case 'onboarding':onboarding();break;
 case 'finish-onboarding':localStorage.setItem('samacha-welcome','1');closeModal();render();break;
 case 'digest':await digestModal();break;
 case 'refresh':busy=true;render();try{await change('/api/refresh',{});startPoll();toast('Gathering your source feeds. Existing records stay available.');}catch(err){busy=false;render();throw err;}break;
 case 'theme':await change('/api/profile',{theme:state.profile.theme==='dark'?'light':'dark'});break;
 case 'tracking':await change('/api/profile',{tracking:!state.profile.tracking});break;
 case 'local-only':await change('/api/profile',{local_only:!state.profile.local_only});break;
 case 'cloud-fallback':if(!state.profile.cloud_fallback&&!confirm('Allow a configured cloud fallback to receive selected source text when the primary fails?'))return;await change('/api/profile',{cloud_fallback:!state.profile.cloud_fallback});break;
 case 'schedule':await change('/api/schedule',{enabled:!state.schedule.enabled});toast(state.schedule.enabled?'Daily in-app briefing enabled while the app host runs.':'Daily routine paused.');break;
 case 'source-toggle':{const id=target.dataset.id;const s=state.sources.find(s=>s.id===id);await change('/api/source',{id,enabled:!s.enabled},true);sourceModal();render();break;}
 case 'clear-history':if(confirm('Delete reading history? Bookmarks and notes remain.')){await change('/api/history/clear',{});toast('Reading history cleared.');}break;
 case 'save-query':if(!query.trim()){toast('Type a search in the top bar first.');document.querySelector('#search').focus();}else{await change('/api/query',{query});toast('Search saved to your library.');}break;
 case 'reset-filters':query='';kind='All';layer='All';mode='For you';missionId='';render();break;
 case 'list':listMode=!listMode;render();break;
 case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('Use your browser menu → Install app / Add to Home screen. HTTPS or localhost is required.');break;
 case 'export-opml':downloadFile('samacha-feeds.opml',`<?xml version="1.0"?><opml version="2.0"><head><title>samacha-RAM</title></head><body>${state.sources.map(s=>`<outline text="${e(s.name)}" title="${e(s.name)}" type="rss" xmlUrl="${e(s.url)}"/>`).join('')}</body></opml>`,'text/xml');break;
 case 'logout':await api('/api/logout',{});localStorage.removeItem('samacha-cache');location.reload();break;
 }
 if(target.dataset.budget){await change('/api/profile',{budget:Number(target.dataset.budget)});}
}
document.addEventListener('click',ev=>{const t=ev.target.closest('[data-nav],[data-act],[data-open],[data-save],[data-kind],[data-mode],[data-library],[data-mission],[data-mission-delete],[data-model-edit],[data-model-delete],[data-model-test],[data-summary],[data-core],[data-budget],[data-mark-read],[data-query],[data-query-delete]');if(t){ev.preventDefault();action(t).catch(err=>toast(err.message));}const a=ev.target.closest('[data-original]');if(a&&!offline&&state.profile.tracking)api('/api/history',{id:a.dataset.original,kind:'original_open'}).catch(()=>{});if(ev.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if((ev.ctrlKey||ev.metaKey)&&ev.key==='k'){ev.preventDefault();document.querySelector('#search')?.focus();}if(ev.key==='Enter'&&ev.target.matches('.card-art'))openArticle(ev.target.dataset.open);if(ev.key==='Tab'&&modalRoot.children.length){const focusables=[...modalRoot.querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
document.addEventListener('change',async ev=>{try{const t=ev.target;if(t.id==='layer-filter'){layer=t.value;render();}if(t.dataset.topic){await change('/api/profile',{topics:{...state.profile.topics,[t.dataset.topic]:t.value}});toast('Interest layer updated.');}if(t.dataset.route){const routes=structuredClone(state.routes);routes[t.dataset.route]||={primary:'builtin',fallback:'none'};routes[t.dataset.route][t.dataset.slot]=t.value;await change('/api/routes',routes);toast('Task route saved.');}if(t.id==='model-kind')toggleAdapter();if(t.id==='opml-file'){const file=t.files[0];if(file.size>150000)throw new Error('OPML import must be smaller than 150 KB.');const preview=await api('/api/opml/preview',{xml:await file.text()});showModal(`<h2>Review your subscriptions.</h2><p class="modal-sub">Select the public feeds to add. Existing subscriptions will be skipped.</p><form id="opml-form">${preview.sources.map((s,i)=>`<label class="check"><input name="feeds" type="checkbox" value="${i}" checked>${e(s.name)}<small>${e(s.url)}</small></label>`).join('')}<button class="primary-btn" type="submit">Add selected sources</button></form>`);document.querySelector('#opml-form')._sources=preview.sources;}if(t.id==='bundle-files')await importBundle(t.files);}catch(err){toast(err.message);}});
async function importBundle(files){if(!files.length)return;const allowed=[...files].filter(f=>/\.(safetensors|json|txt|model)$/.test(f.name));if(!allowed.length)throw new Error('Choose a folder with config, tokenizer, and safetensors files.');const bundle=files[0].webkitRelativePath.split('/')[0];if(!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,100}$/.test(bundle))throw new Error('Rename the folder using letters, numbers, dots, underscores, or hyphens.');if(!confirm(`Upload ${allowed.length} files (${(allowed.reduce((n,f)=>n+f.size,0)/1024**2).toFixed(0)} MiB) to your app host? Review the model license first.`))return;const el=document.querySelector('#import-progress');for(let i=0;i<allowed.length;i++){const f=allowed[i];el.textContent=`Importing file ${i+1} of ${allowed.length}: ${f.name}`;const path=f.webkitRelativePath.split('/').slice(1).join('/');const r=await fetch('/api/models/upload?'+new URLSearchParams({bundle,path}),{method:'POST',headers:{'X-Samacha':'1','Content-Type':'application/octet-stream'},body:f});if(!r.ok)throw new Error((await r.json()).error);}el.textContent=`Imported to ${bundle}. Register it with Add model to test compatibility.`;toast('Model files imported. Register the bundle to choose its task.');}
document.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target;if(!f.id)return;const button=f.querySelector('[type=submit]');if(button)button.disabled=true;const data=new FormData(f);try{
 if(f.id==='login-form'){await api('/api/login',{password:data.get('password')});await boot();}
 if(f.id==='mission-form'){await change('/api/mission',{title:data.get('title'),expires:data.get('expires'),topics:data.getAll('topics')});closeModal();page='missions';render();toast('Mission created. Your core interests are unchanged.');}
 if(f.id==='source-form'){await change('/api/source',{name:data.get('name'),url:data.get('url'),kind:data.get('kind')},true);sourceModal();render();toast('Feed added. Refresh sources to fetch entries.');}
 if(f.id==='model-form'){const b=Object.fromEntries(data);b.id=f.dataset.id||undefined;b.capabilities=data.getAll('capabilities');b.local=data.has('local');b.allow_cloud=data.has('allow_cloud');b.clear_key=data.has('clear_key');await change('/api/models',b);closeModal();toast('Model registered. Assign it to a task, then test inference.');}
 if(f.id==='playground'){const resultEl=document.querySelector('#play-result');resultEl.innerHTML='<p class="source-note">Running the selected route…</p>';try{const r=await api('/api/run',Object.fromEntries(data));resultEl.innerHTML=resultHTML(r);}catch(err){resultEl.innerHTML=`<div class="result danger">${e(err.message)}</div>`;}}
 if(f.id==='note-form'){await change('/api/save',{id:f.dataset.id,active:true,note:data.get('note')},true);render();toast('Note saved with this source.');}
 if(f.id==='reader-qa'){const resultEl=document.querySelector('#qa-result');resultEl.innerHTML='<p class="source-note">Looking within this excerpt…</p>';const r=await api('/api/run',{article_id:f.dataset.id,task:'qa',question:data.get('question')});resultEl.innerHTML=resultHTML(r);}
 if(f.id==='schedule-form'){await change('/api/profile',Object.fromEntries(data));toast('Daily routine saved.');}
 if(f.id==='download-form'){await change('/api/models/download',{repo:data.get('repo'),revision:data.get('revision'),license_ack:data.has('license_ack')});closeModal();startPoll();toast('Download queued. Check Model studio for its actual status.');}
 if(f.id==='opml-form'){let added=0,failed=0;for(const index of data.getAll('feeds')){const s=f._sources[Number(index)];if(state.sources.some(x=>x.url===s.url))continue;try{await api('/api/source',s);added++;}catch{failed++;}}await sync();closeModal();render();toast(`${added} sources added${failed?`; ${failed} rejected` :''}. Refresh when ready.`);}
 }catch(err){toast(err.message);}finally{if(button)button.disabled=false;}});
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev;});
window.addEventListener('online',()=>{sync().then(render).catch(()=>{});});
function login(){app.innerHTML=`<main class="login"><div class="logo"><div class="brandmark">s<span>r</span></div><div class="wordmark">samacha·RAM</div></div><h1>Your reading space.</h1><p>Sign in to your personal app host. This is a single-owner workspace.</p><form id="login-form"><div class="field"><label for="password">App password</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><button class="primary-btn" type="submit">Open workspace ${icon('arrow')}</button></form></main>`;}
async function boot(){try{const session=await api('/api/session');if(!session.authenticated){login();return;}await sync();render();if(!localStorage.getItem('samacha-welcome'))onboarding();if('serviceWorker'in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});}catch(err){try{state=JSON.parse(localStorage.getItem('samacha-cache'));if(!state)throw err;offline=true;render();}catch{app.innerHTML=`<main class="login"><h1>A quiet connection.</h1><p>${e(err.message)}. Start the app host and reload to connect.</p><button class="primary-btn" id="reload">Try again</button></main>`;document.querySelector('#reload').onclick=()=>location.reload();}}}
boot();
